/*
Product vision, requirements, architecture direction and delivery leadership: Andrews Mensah.
*/
import {money} from './engine.mjs';
import {icon} from './icons.mjs';
import {workspaceFor,PAGE_LABELS,summarize,worklist} from './workspaces.mjs';
import {createStudioAdapter} from './studio-adapter.mjs';
const STUDIO=document.body.dataset.runtime==='studio';
const studio=STUDIO?createStudioAdapter(await fetch('./cost-model.json').then(r=>r.json()),localStorage):null;
let dialogState=null,quoteTab='estimate',selectedQuoteId=null,patientSearch='',approvalTab='clinical',taskFilter='all',selectedPlanId=null;
const app=document.querySelector('#app');let user=null,csrf='',catalog=[],model={},policy={},workspace={patients:[],plans:[],quotes:[],finance:[],payments:[]},busy=false;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const can=(...roles)=>roles.includes(user?.role);
const title=(t,s,actions='')=>`<div class="page-heading"><div><div class="eyebrow">CLARITY DENTAL WORKSPACE</div><h1>${t}</h1><p class="sub">${s}</p></div>${actions?`<div class="heading-actions">${actions}</div>`:''}</div>`;
const pill=(s,w=false)=>`<span class="pill ${w?'warn':''}">${esc(s)}</span>`;
const patient=id=>workspace.patients.find(p=>p.id===id)?.reference||id;
const family=code=>catalog.find(c=>c.code===code)?.name||code;
const opts=(items,value,label)=>items.map(i=>`<option value="${esc(value(i))}">${esc(label(i))}</option>`).join('');
const field=(label,input)=>`<div class="field"><label>${label}${input}</label></div>`;
const cents=s=>{if(!/^\d{1,7}(\.\d{1,2})?$/.test(s))throw Error('Enter dollars with at most two decimals');const [w,f='']=s.split('.');return Number(w)*100+Number(f.padEnd(2,'0'));};
function toast(message,error=false){const e=document.querySelector('#toast');e.textContent=message;e.className=error?'error':'';e.hidden=false;clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>e.hidden=true,6000);}
async function api(path,body,method=body===undefined?'GET':'POST'){
 if(studio)return studio.request(path,body);
 const key=crypto.randomUUID();const request={method,headers:{'Content-Type':'application/json','X-CSRF-Token':csrf,'Idempotency-Key':key},credentials:'same-origin',...(body!==undefined?{body:JSON.stringify(body)}:{})};
 let response;try{response=await fetch(path,request);}catch{response=await fetch(path,request);}
 let data;try{data=await response.json();}catch{throw Error('Server returned an unreadable response');}
 if(!response.ok){if(response.status===401){user=null;render();}throw Error(data.error||`Request failed (${response.status})`);}return data;
}
function login(){return `<section class="panel login"><h1>Welcome to Clarity</h1><p class="sub">Sign in to the Clarity Dental workspace.</p><form data-form="login">${field('Role account',`<select name="username">${['coordinator','dentist','reviewer','director','patient'].map(v=>`<option>${v}</option>`).join('')}</select>`)}${field('Password','<input name="password" type="password" autocomplete="current-password" required maxlength="128">')}<button>Sign in</button><button type="button" id="sample-login" class="secondary">Open sample workspace</button><p class="small">Local seeded accounts use <code>Clarity-Demo-2026!</code> unless DEMO_PASSWORD was set before the database was created. Choose an account to explore its role in the project.</p></form><div class="notice">Use coordinator to create plans and estimates, dentist for clinical approval and completion, reviewer for exceptions, director for simulated provider events, and patient for acceptance. Changing roles requires signing out.</div></section>`;}
function crm(){const visible=workspace.patients.filter(p=>p.reference.toLowerCase().includes(patientSearch.toLowerCase()));return title('Patient relationships. Connected.','One view of consent, care plans and each patient’s next step.',can('admin','coordinator')?`<button data-dialog="patient">${icon('plus')}Add patient</button>`:'')+`<section class="panel flush"><div class="panel-head"><div><h2>Patient workspace</h2><p class="small">${workspace.patients.length} patient records</p></div><div class="field"><input id="patient-search" placeholder="Find a patient…" aria-label="Find a patient" value="${esc(patientSearch)}"></div></div><div class="table-wrap"><table><thead><tr><th>PATIENT</th><th>CARE PLANS</th><th>CONTACT CONSENT</th><th>ESTIMATE STATUS</th><th></th></tr></thead><tbody>${visible.map((p,i)=>`<tr><td><div class="person"><span class="avatar ${i%2?'sage':'lilac'}">P${i+1}</span><span><strong>${esc(p.reference)}</strong><small>Patient record · v${p.version}</small></span></div></td><td>${workspace.plans.filter(t=>t.patientId===p.id).length} care plans</td><td>${pill(p.contactConsent?'Consent recorded':'Consent pending',!p.contactConsent)}</td><td>${workspace.quotes.filter(q=>q.patientId===p.id).length} decisions</td><td><button class="text-button" data-patient="${p.id}">Open profile ${icon('chevron')}</button></td></tr>`).join('')}</tbody></table></div><div class="panel-footer"><span>Patient-scoped access and versioned consent</span><span>${visible.length} shown</span></div></section>`;}

function plans(){return title(can('patient')?'Your treatment, step by step.':'Care plans. Clearly coordinated.',can('patient')?'Your care plan, visit progress and next appointment in one place.':'Clinical approval, appointments and progress — connected from the first visit.',can('admin','coordinator','clinician')?`<button data-dialog="plan">${icon('plus')}New treatment plan</button>`:'')+`${selectedPlanId?'<div class="selection-context"><span>Focused treatment plan</span><button class="text-button" data-clear-plan>Show all plans</button></div>':''}<div class="grid equal">${workspace.plans.length?workspace.plans.filter(p=>!selectedPlanId||p.id===selectedPlanId).map(p=>`<section class="panel"><div class="panel-head"><div class="person"><span class="avatar sage">${icon('tooth')}</span><span><strong>${esc(family(p.family))}</strong><small>${esc(patient(p.patientId))}</small></span></div>${pill(p.status==='DRAFT'?'Awaiting approval':p.status.replaceAll('_',' '),p.status==='DRAFT')}</div><div class="plan-meta"><span>${icon('clock')} ${p.minutes} chair minutes</span><span>${icon('layers')} ${catalog.find(c=>c.code===p.family)?.visits} pathway visits</span><span>v${p.version}</span></div><div class="plan-pathway">${Array.from({length:catalog.find(c=>c.code===p.family)?.visits||1},(_,i)=>`<span class="path-step ${p.appointments[i]?.status==='COMPLETED'?'done':''}"></span>`).join('')}</div><p class="small">${p.appointments.filter(a=>a.status==='COMPLETED').length} visits completed · ${can('patient')?'Your care team coordinates the next step':money(Math.round(p.lab*100))+' laboratory cost'}</p>${p.status==='DRAFT'&&can('clinician')?`<button data-action="approve" data-id="${p.id}">${icon('check')}Clinically approve</button>`:''}${['APPROVED','SCHEDULED'].includes(p.status)&&can('admin','coordinator','clinician')?`<form data-form="schedule" data-id="${p.id}" class="inline">${field('Next appointment','<input name="when" type="datetime-local" required>')}<button class="secondary">Schedule visit</button></form>`:''}${p.appointments.map(a=>`<div class="row"><span>${esc(new Date(a.when).toLocaleString())}<br>${pill(a.status)}</span>${a.status==='SCHEDULED'&&can('clinician')?`<button class="secondary" data-action="complete" data-id="${p.id}" data-visit="${a.id}" ${Date.parse(a.when)>Date.now()?'disabled':''}>Complete visit</button>`:''}</div>`).join('')}${!['COMPLETED','CANCELLED'].includes(p.status)&&can('admin','coordinator','clinician')?`<details><summary>Pathway actions</summary><button class="danger" data-action="cancel" data-id="${p.id}">Cancel pathway</button></details>`:''}</section>`).join(''):`<section class="panel empty"><div class="empty-symbol">${icon('tooth')}</div><h3>Your care pathways start here</h3><p>Create a treatment plan, then have it reviewed by the clinician.</p>${can('admin','coordinator','clinician')?'<button data-dialog="plan">Create a plan</button>':'<p class="small">Your care team will prepare your treatment plan.</p>'}</section>`}</div>`;}

function quotes(){const active=workspace.plans.filter(p=>['APPROVED','SCHEDULED'].includes(p.status)&&!workspace.quotes.some(q=>q.planId===p.id&&q.accepted));const q=workspace.quotes.find(q=>q.id===selectedQuoteId)||workspace.quotes.find(q=>q.route==='ISSUED'&&!q.accepted)||workspace.quotes[0];return title(can('patient')?'Understand your treatment estimate.':'A confident price. A clear explanation.',can('patient')?'Review your itemized amounts and choose the next step when you are ready.':'Bring learned cost, financial policy and patient choice into one decision.',can('admin','coordinator','clinician')?`<button class="secondary" data-dialog="plan">${icon('plus')}Create care plan</button>`:'')+`<div class="grid">${can('admin','coordinator')?`<section class="panel"><div class="panel-head"><h2>Configure an estimate</h2>${pill('Model-driven')}</div><form data-form="quote">${field('Approved treatment plan',`<select name="planId" required>${opts(active,p=>p.id,p=>`${patient(p.patientId)} · ${family(p.family)}`)}</select>`)}${!active.length?'<p class="notice">Create and approve a new plan to evaluate another estimate.</p>':''}<div class="form-section">Payment & benefits</div>${field('Benefits verification','<select name="benefits"><option value="CURRENT">Current benefits scenario</option><option value="STALE">Needs refresh — test blocked route</option></select>')}${field('Patient deposit · USD','<input name="deposit" type="text" inputmode="decimal" value="0" required pattern="[0-9]+([.][0-9]{1,2})?">')}<label><input name="insurance" type="checkbox">Apply fixed payer contract scenario</label><label><input name="loyalty" type="checkbox">Apply eligible 5% loyalty benefit</label><label><input name="financing" type="checkbox">Include financing cost assumption</label><div class="insight-callout">${icon('shield')}<div><strong>Policy is checked before issue.</strong><p>Fee movement, margin, contract precedence and deposit limits stay enforced.</p></div></div><button class="wide" ${active.length?'':'disabled'}>${icon('sparkle')}Evaluate estimate ${icon('arrow')}</button></form></section>`:''}<section class="panel"><div class="panel-head"><h2>Decision workspace</h2>${q?pill(q.route==='ISSUED'?'Policy checked':'Review required',q.route!=='ISSUED'):''}</div><div class="quote-tabs">${[['estimate','Estimate'],['model','Model evidence'],['history','Decision history']].filter(([id])=>!can('patient')||id==='estimate').map(([id,label])=>`<button class="segment ${quoteTab===id?'active':''}" data-quote-tab="${id}">${label}</button>`).join('')}</div>${quoteTab==='history'?workspace.quotes.map(h=>`<div class="history-row"><span><strong>${esc(patient(h.patientId))}</strong><span class="small"> · ${esc(family(h.input.family))}</span><br>${pill(h.route,h.route==='REVIEW')}</span><button class="text-button" data-open-quote="${h.id}">Inspect ${icon('arrow')}</button></div>`).join('')||'<p class="small">Decision history appears after your first estimate.</p>':quoteTab==='model'?q?`<h3>Clarity Cost Model · Version 2</h3><p class="small">Treatment family, chair minutes and lab cost inform the delivery-cost prediction.</p><div class="model-metric-grid">${[['Predicted cost',money(q.cost.mean)],['Lower interval',money(q.cost.lower)],['Upper interval',money(q.cost.upper)]].map(([l,v])=>`<div class="model-metric"><small>${l}</small><strong>${v}</strong></div>`).join('')}</div><div class="insight-callout">${icon('sparkle')}<div><strong>Prediction meets policy.</strong><p>The optimizer checks the permitted price range and uses the upper cost interval in the self-pay margin constraint.</p></div></div><a class="text-button" href="#evidence">Explore model methodology ${icon('arrow')}</a>`:'<p class="small">Evaluate an estimate to inspect model evidence.</p>':q?quoteCard(q):`<div class="empty"><div class="empty-symbol">${icon('sparkle')}</div><h3>Ready for a clearer estimate?</h3><p>Choose an approved care plan and evaluate its price. Your decision evidence will appear here.</p></div>`}</section></div>`;}

function quoteCard(q){return `<div class="person"><span class="avatar sage">${icon('tooth')}</span><span><strong>${esc(patient(q.patientId))}</strong><small>${esc(family(q.input.family))} · decision ${esc(q.id.slice(0,8))}</small></span></div>${q.route==='ISSUED'?`<div class="estimate-header"><div class="label">Estimated patient responsibility</div><div class="total">${money(q.patient)}</div><small>${q.accepted?'Patient acceptance recorded':'Ready to explain'} · valid through ${esc(new Date(q.expires).toLocaleDateString('en-US',{month:'short',day:'numeric'}))}</small></div>${[['Treatment fee',q.net],['Estimated payer contribution',-q.payer],['Patient deposit',-q.deposit],['Subsequent payment entries',-q.ledger.paid],['Sandbox funding',-q.ledger.funded]].map(([a,b])=>`<div class="row"><span>${a}</span><strong>${money(b)}</strong></div>`).join('')}<div class="row balance"><span>Remaining patient balance</span><strong>${money(q.ledger.remaining)}</strong></div>${!q.accepted&&can('patient','coordinator')?`<form data-form="accept" data-id="${q.id}"><label><input name="consent" type="checkbox" required>I accept this estimate and its itemized amounts.</label><button class="wide">${icon('check')}Record patient acceptance</button></form>`:''}${q.accepted&&q.ledger.remaining>0&&can('coordinator','admin')?`<form data-form="payment" data-id="${q.id}" class="inline">${field('Payment entry · USD','<input name="amount" type="text" inputmode="decimal" placeholder="0.00" required>')}<button class="secondary">Record payment</button></form>`:''}${q.accepted&&q.ledger.remaining>0&&can('coordinator','patient')&&!workspace.finance.some(f=>f.quoteId===q.id&&!['DECLINED','WITHDRAWN','REFUNDED'].includes(f.status))?`<form data-form="finance" data-id="${q.id}"><label><input name="consent" type="checkbox" required>I separately consent to a sandbox financing application.</label><button class="secondary">Explore financing ${icon('arrow')}</button></form>`:''}`:`<div class="notice">${icon('shield')}<strong>Automatic issue paused.</strong><br>${esc(q.reason)}</div><p class="small">Reason ${esc(q.code)} · Required constraints remain enforced.</p>${q.disposition?pill(q.disposition):can('reviewer')?`<form data-form="review" data-id="${q.id}"><div class="field"><label>Review disposition<select name="disposition"><option>SOURCE_REWORK</option><option>POLICY_REVIEW</option></select></label></div><button>Record review disposition</button></form>`:'<p class="small">Switch to the reviewer perspective to record a disposition.</p>'}`}<div class="modal-actions"><span class="small">Pricing Policy 2 · v${q.version}</span><button class="text-button" data-action="export" data-id="${q.id}">${icon('download')}Export decision</button></div>`;}

function finances(){return title('Patient choice. Connected financing.','Follow applications from submission to offer, separate consent and settlement.',pill('Sandbox connection',true))+`<div class="stats">${[['In progress',workspace.finance.filter(f=>['PENDING','OFFERED','ACCEPTED'].includes(f.status)).length,'clock'],['Offers available',workspace.finance.filter(f=>f.status==='OFFERED').length,'wallet'],['Funded',workspace.finance.filter(f=>f.status==='FUNDED').length,'check'],['Closed',workspace.finance.filter(f=>['DECLINED','WITHDRAWN','REFUNDED'].includes(f.status)).length,'shield']].map(([l,v,i])=>`<div class="stat"><div class="stat-top">${l}<span class="stat-icon">${icon(i)}</span></div><b>${v}</b><span class="stat-foot">Application states in this workspace</span></div>`).join('')}</div><div class="grid equal">${workspace.finance.length?workspace.finance.map(f=>`<section class="panel"><div class="panel-head"><div class="person"><span class="avatar lilac">${icon('wallet')}</span><span><strong>${esc(patient(f.patientId))}</strong><small>Application ${esc(f.id.slice(0,8))}</small></span></div>${pill(f.status,f.status==='PENDING')}</div><div class="mini-finance"><div><p>Financing amount</p><strong>${money(f.amount)}</strong></div>${pill('Patient choice','')}</div><div class="finance-stages">${['PENDING','OFFERED','ACCEPTED','FUNDED'].map((state,i)=>`<span class="finance-stage ${['PENDING','OFFERED','ACCEPTED','FUNDED'].indexOf(f.status)>=i?'done':''}">${['Submitted','Offer','Consent','Funded'][i]}</span>`).join('')}</div>${can('admin')&&f.status==='PENDING'?`<button data-action="provider-offer" data-id="${f.id}">Send test offer</button><button class="danger" data-action="provider-decline" data-id="${f.id}">Send test decline</button>`:''}${can('patient','coordinator')&&f.status==='OFFERED'?`<form data-form="offer" data-id="${f.id}"><label><input name="consent" type="checkbox" required>I separately accept this sandbox offer.</label><button>Accept offer ${icon('arrow')}</button></form>`:''}${can('admin')&&f.status==='ACCEPTED'?`<button data-action="provider-fund" data-id="${f.id}">Record sandbox funding</button>`:''}${can('admin')&&f.status==='FUNDED'?`<button class="secondary" data-action="provider-refund" data-id="${f.id}">Record sandbox refund</button>`:''}${can('patient','coordinator')&&['PENDING','OFFERED','ACCEPTED'].includes(f.status)?`<button class="text-button" data-action="withdraw" data-id="${f.id}">Withdraw application</button>`:''}<p class="section-note">Separate offer consent is required before funding. Workflow adapter: local sandbox.</p></section>`).join(''):`<section class="panel empty"><div class="empty-symbol">${icon('wallet')}</div><h3>Financing starts with patient choice.</h3><p>Accept an estimate, then record separate application consent in the pricing workspace.</p><a class="button" href="#quotes">Open pricing ${icon('arrow')}</a></section>`}</div>`;}

function evidence(){return title('Intelligence you can inspect.','Understand the model, the pricing controls and the evidence behind each decision.')+`<div class="grid equal"><section class="panel"><div class="panel-head"><h2>Clarity Cost Model</h2>${pill('Version 2')}</div><p class="small">A trained ridge model connects treatment family, chair time and lab cost to estimated delivery cost.</p><div class="model-metric-grid">${[['Training rows',model.training_rows],['Calibration rows',model.calibration_rows],['Test rows',model.test_rows]].map(([l,v])=>`<div class="model-metric"><small>${l}</small><strong>${v.toLocaleString()}</strong></div>`).join('')}</div><div class="row"><span>Supported families</span><strong>16</strong></div><div class="row"><span>Residual interval radius</span><strong>${money(Math.round(model.interval_radius_usd*100))}</strong></div><div class="row"><span>Inference path</span><strong>${STUDIO?'Browser workspace':'Server API'}</strong></div><div class="insight-callout">${icon('sparkle')}<div><strong>Learned costs. Enforced constraints.</strong><p>Model estimates feed a deterministic optimizer. Exact financial amounts use integer cents and basis points.</p></div></div><p class="section-note">Evaluation methodology and generated-data provenance are recorded in Project details.</p></section><section class="panel"><div class="panel-head"><h2>Pricing control framework</h2>${pill('Policy 2')}</div>${[['shield','Clinical authority','Clinician approval precedes pricing.'],['activity','Price stability','Self-pay gross fees stay within ±5%.'],['wallet','Financial precision','Deposits, payer and patient amounts reconcile.'],['layers','Decision integrity','Versions and workflow state remain explicit.']].map(([i,h,t])=>`<div class="list-item"><div class="person"><span class="avatar sage">${icon(i)}</span><span><strong>${h}</strong><small>${t}</small></span></div></div>`).join('')}${can('admin','reviewer')?'<button class="secondary" data-action="audit">Inspect activity & audit</button><div id="audit-output"></div>':'<p class="section-note">Director and reviewer perspectives can inspect the audit trail.</p>'}</section></div>`;}

function projectStatus(){return title('Product leadership & project details.','The vision, operating environment and delivery evidence behind Clarity Dental.')+`<div class="grid equal"><section class="panel"><div class="drawer-patient"><span class="avatar sage">AM</span><span><h2>Andrews Mensah</h2><span class="small">AI Product Director · Product Owner</span></span></div><p class="small">Andrews defined the product vision, treatment and financing journeys, CRM requirements, architectural direction and delivery priorities. He led the UI/UX direction, role-based interaction design, implementation, testing and refinement of the platform.</p><div class="pillrow">${pill('Product strategy')}${pill('Architecture direction')}${pill('Delivery leadership')}</div><hr><h3>Design & interaction</h3><p class="small">The visual workspace uses an embedded GrapesJS editor. You can select layers, revise styles, preview responsive layouts and export editable project data. The working application runs separately from canvas edits.</p><a class="button secondary" href="designer.html">${icon('edit')}Open design studio</a></section><section class="panel"><h2>Operating environment</h2><div class="row"><span>Workspace runtime</span><strong>${STUDIO?'Interactive browser studio':'Node / SQLite application'}</strong></div><div class="row"><span>Evaluation records</span><strong>Generated project fixtures</strong></div><div class="row"><span>Financing</span><strong>Local sandbox; simulated funds</strong></div><div class="row"><span>External adapters</span><strong>Partner configuration required</strong></div><p class="section-note">The cost model is trained and evaluated on generated records. Its evaluation results describe that dataset. Aspen Dental, Synchrony and Zest AI inform the integration design; vendor relationships and live clinical/lender connections are established separately.</p><p class="section-note">${STUDIO?'Browser records stay on this device; role perspectives support walkthroughs rather than real identity verification.':'Server sessions, roles, transactions and audit support the application workflow.'}</p><a class="text-button" href="https://github.com/anmensah44-spec/dental-pricing-ai-prototype" target="_blank" rel="noopener">View source and validation ${icon('arrow')}</a></section></div>`;}

function render(){
 const profile=workspaceFor(user?.role),pages=profile.pages;const page=pages.includes(location.hash.slice(1))?location.hash.slice(1):'overview';const labels={...PAGE_LABELS,overview:profile.short,plans:can('patient')?'My treatment':'Treatment plans',quotes:can('patient')?'My estimates':'Pricing & estimates',finance:can('patient')?'My financing':'Financing'};
 document.querySelector('#page-title').textContent=labels[page];document.querySelector('#account').innerHTML=user?`${STUDIO?`<label class="perspective-label">View as<select id="role-perspective" aria-label="Workspace perspective">${Object.entries({coordinator:'Nursing & coordination',dentist:'Dentist / clinician',reviewer:'Pricing & risk reviewer',director:'Executive / director',patient:'Patient'}).map(([id,label])=>`<option value="${id}" ${user.id===id?'selected':''}>${label}</option>`).join('')}</select></label>`:`<span class="small">${esc(profile.name)}</span><button id="logout" class="icon-button" aria-label="Sign out">${icon('logout')}</button>`}<span class="avatar sage">${user.id==='director'?'AM':user.id.slice(0,2).toUpperCase()}</span>`:'';
 document.querySelector('.workspace-switch').innerHTML=`<span class="workspace-logo">${icon(profile.icon)}</span><span>${esc(profile.short)}<small>${can('patient')?'Your connected care journey':'Clarity Dental'}</small></span>`;
 document.querySelector('#nav').innerHTML=user?`<div class="nav-label">${can('patient')?'YOUR CARE':'YOUR WORKSPACE'}</div>${pages.map(v=>`<a href="#${v}" class="${v===page?'active':''}" ${v===page?'aria-current="page"':''}>${icon(({overview:'grid',crm:'users',plans:'tooth',approvals:'check',quotes:'sparkle',finance:'wallet',evidence:'shield',status:'info'})[v])}<span>${labels[v]}</span>${v==='approvals'&&summarize(workspace).drafts.length+summarize(workspace).reviews.length?`<span class="nav-count">${summarize(workspace).drafts.length+summarize(workspace).reviews.length}</span>`:''}</a>`).join('')}`:'';
 app.innerHTML=(user?({overview,crm,plans,approvals,quotes,finance:finances,evidence,status:projectStatus})[page]():login())+(user&&dialogState?dialogMarkup(): '');bind();bindInteractions();if(dialogState){const dialog=document.querySelector('dialog');dialog?.showModal();dialog?.addEventListener('cancel',e=>{e.preventDefault();dialogState=null;render();});}
}

async function refresh(){workspace=await api('/api/workspace');render();}
async function run(fn){if(busy)return;busy=true;document.querySelectorAll('#app button').forEach(b=>b.disabled=true);try{await fn();}catch(e){toast(e.message,true);}finally{busy=false;render();}}
function bind(){
 document.querySelector('#sample-login')?.addEventListener('click',e=>{const f=e.target.form;f.elements.password.value='Clarity-Demo-2026!';f.requestSubmit();});
 document.querySelector('#logout')?.addEventListener('click',()=>run(async()=>{await api('/api/logout',{});user=null;csrf='';}));
 document.querySelector('#family')?.addEventListener('change',e=>{const c=catalog.find(c=>c.code===e.target.value),f=e.target.form;f.elements.minutes.value=c.minutes;f.elements.lab.value=c.lab;document.querySelector('#pathway').textContent=`${c.visits} illustrative visits; actual sequence and duration require clinician judgment.`;});
 document.querySelectorAll('form[data-form]').forEach(f=>f.addEventListener('submit',event=>{event.preventDefault();run(async()=>{const form=new FormData(f),b=Object.fromEntries(form),id=f.dataset.id,type=f.dataset.form;
  if(type==='login'){const s=await api('/api/login',b);user=s.user;csrf=s.csrf;const c=await api('/api/catalog');catalog=c.catalog;model=c.model;policy=c.policy;await refresh();return;}
  if(type==='patient')await api('/api/patients',b);
  if(type==='plan')await api('/api/plans',{...b,minutes:Number(b.minutes),lab:Number(b.lab)});
  if(type==='schedule'){const p=workspace.plans.find(p=>p.id===id);await api(`/api/plans/${id}/schedule`,{version:p.version,when:new Date(b.when).toISOString()});}
  if(type==='quote'){const p=workspace.plans.find(p=>p.id===b.planId);const result=await api('/api/quotes',{planId:p.id,planVersion:p.version,benefits:b.benefits,deposit:cents(b.deposit),insurance:form.has('insurance'),loyalty:form.has('loyalty'),financing:form.has('financing')});selectedQuoteId=result.id;quoteTab='estimate';}
  if(['accept','payment','finance','review'].includes(type)){const q=workspace.quotes.find(q=>q.id===id);await api(`/api/quotes/${id}/${type}`,{version:q.version,...(type==='payment'?{amount:cents(b.amount)}:type==='review'?{disposition:b.disposition}:{consent:form.has('consent')})});}
  if(type==='offer'){const x=workspace.finance.find(x=>x.id===id);await api(`/api/finance/${id}/accept-offer`,{version:x.version,consent:form.has('consent')});}
  dialogState=null;await refresh();toast('Saved to the decision trail.');});}));
 document.querySelectorAll('[data-action]').forEach(b=>b.addEventListener('click',()=>run(async()=>{const {action,id,visit}=b.dataset;
  if(action==='consent'){const p=workspace.patients.find(p=>p.id===id);await api(`/api/patients/${id}/consent`,{version:p.version,consent:!p.contactConsent});}
  if(['approve','cancel','complete'].includes(action)){const p=workspace.plans.find(p=>p.id===id);await api(`/api/plans/${id}/${action==='complete'?'complete-visit':action}`,{version:p.version,...(visit?{appointmentId:visit}:{})});}
  if(action.startsWith('provider-')||action==='withdraw'){const x=workspace.finance.find(x=>x.id===id);await api(`/api/finance/${id}/${action==='withdraw'?'withdraw':'provider-event'}`,{version:x.version,...(action==='withdraw'?{}:{source:'local-simulator',event:action.slice(9)})});}
  if(action==='export'){const data=await api(`/api/quotes/${id}/export`),blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`clarity-quote-${id}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);return;}
  if(action==='audit'){const data=await api('/api/audit');window.auditData=data;return;}
  await refresh();toast('Action saved.');})));}
window.addEventListener('hashchange',()=>{document.querySelector('.sidebar')?.classList.remove('is-open');dialogState=null;render();});
async function start(){try{const s=await api('/api/session');user=s.user;csrf=s.csrf;const c=await api('/api/catalog');catalog=c.catalog;model=c.model;policy=c.policy;workspace=await api('/api/workspace');}catch(e){if(user)toast(e.message,true);}render();}
// Audit data is rendered as escaped text after asynchronous actions complete.
const baseRender=render;
render=function(){baseRender();if(window.auditData&&location.hash==='#evidence'&&can('admin','reviewer'))document.querySelector('#audit-output').innerHTML=`<p>${pill(window.auditData.storage==='browser'?'Browser activity trail':window.auditData.verified?'Hash chain verified':'Integrity check failed',!window.auditData.verified)}</p><pre class="code-evidence">${esc(JSON.stringify(window.auditData.events.map(e=>({sequence:e.seq,time:e.time,actor:e.actor,activity:e.action.replace('SYNTHETIC_',''),record:e.entity,digest:e.digest})),null,2))}</pre>`;};

function planForm(){return `<form data-form="plan">${field('Patient',`<select name="patientId">${opts(workspace.patients,p=>p.id,p=>p.reference)}</select>`)}${field('Treatment family',`<select name="family" id="family">${opts(catalog,c=>c.code,c=>c.name)}</select>`)}<div class="fieldgrid">${field('Chair minutes','<input name="minutes" type="number" min="15" max="180" step="1" value="45" required>')}${field('Laboratory cost · USD','<input name="lab" type="number" min="0" max="1500" step="1" value="0" required>')}</div><p id="pathway" class="small">Choose a treatment to load its pathway configuration.</p><button class="wide">Create draft plan ${icon('arrow')}</button></form>`;}
function dialogMarkup(){
 const head=(label)=>`<div class="modal-head"><h2>${label}</h2><button class="icon-button" data-close-dialog aria-label="Close dialog">${icon('close')}</button></div>`;
 if(dialogState==='search')return `<dialog class="modal" aria-label="Search workspace"><input class="command-input" id="command-search" placeholder="Find a workspace or patient…" aria-label="Search pages and patients"><div id="command-list" class="command-list">${commandOptions('')}</div></dialog>`;
 if(dialogState==='plan')return `<dialog class="modal" aria-label="New treatment plan">${head('Start a treatment journey')}<div class="modal-body"><p class="sub">Configure care, then request clinical approval before pricing.</p>${planForm()}</div></dialog>`;
 if(dialogState==='patient')return `<dialog class="modal" aria-label="Add patient">${head('Create a patient record')}<div class="modal-body"><p class="sub">Start with a project patient reference and build the care journey.</p><form data-form="patient">${field('Patient reference','<input name="reference" placeholder="Demo patient 004" pattern="Demo patient [A-Za-z0-9 -]{1,20}" maxlength="33" required>')}<button class="wide">Create patient record ${icon('arrow')}</button></form></div></dialog>`;
 const p=workspace.patients.find(p=>p.id===dialogState.patient);if(!p)return '';
 return `<dialog class="modal drawer" aria-label="Patient profile">${head('Patient workspace')}<div class="modal-body"><div class="drawer-patient"><span class="avatar lilac">P${p.id.slice(-1)}</span><span><h2>${esc(p.reference)}</h2><span class="small">Connected care-to-cost journey</span></span></div><div class="row"><span>Contact consent</span>${pill(p.contactConsent?'Recorded':'Pending',!p.contactConsent)}</div>${can('admin','coordinator','patient')?`<button class="secondary" data-action="consent" data-id="${p.id}">${p.contactConsent?'Withdraw':'Record'} contact consent</button>`:''}<hr><h2>Care plans</h2>${workspace.plans.filter(t=>t.patientId===p.id).map(t=>`<div class="list-item"><h3>${esc(family(t.family))}</h3>${pill(t.status,t.status==='DRAFT')}<p class="section-note">${t.minutes} chair minutes · ${t.appointments.length} appointments scheduled</p></div>`).join('')||'<p class="small">No care plans yet.</p>'}<hr><h2>Pricing decisions</h2>${workspace.quotes.filter(q=>q.patientId===p.id).map(q=>`<div class="history-row"><span><strong>${esc(family(q.input.family))}</strong><br>${pill(q.route,q.route==='REVIEW')}</span><button class="text-button" data-open-quote="${q.id}">${q.route==='ISSUED'?money(q.patient):'Review'} ${icon('chevron')}</button></div>`).join('')||'<p class="small">No pricing decisions yet.</p>'}</div></dialog>`;
}
function commandOptions(query){const pages=workspaceFor(user?.role).pages.map(page=>[PAGE_LABELS[page],page,({overview:'grid',crm:'users',plans:'tooth',approvals:'check',quotes:'sparkle',finance:'wallet',evidence:'shield',status:'info'})[page]]);return pages.filter(([label])=>label.toLowerCase().includes(query.toLowerCase())).map(([label,page,i])=>`<button class="command-option" data-command-page="${page}"><span>${icon(i)}${label}</span>${icon('arrow')}</button>`).join('')+workspace.patients.filter(p=>p.reference.toLowerCase().includes(query.toLowerCase())).map(p=>`<button class="command-option" data-patient="${p.id}"><span>${icon('users')}${esc(p.reference)}</span>${icon('chevron')}</button>`).join('');}
function bindCommandResults(){document.querySelectorAll('[data-command-page]').forEach(b=>b.onclick=()=>{dialogState=null;location.hash=b.dataset.commandPage;render();});document.querySelectorAll('[data-patient]').forEach(b=>b.onclick=()=>{dialogState={patient:b.dataset.patient};render();});}
function bindInteractions(){
 document.querySelectorAll('#nav a').forEach(a=>a.onclick=()=>{selectedPlanId=null;dialogState=null;taskFilter='all';});
 document.querySelector('#mobile-menu').onclick=()=>document.querySelector('.sidebar').classList.toggle('is-open');
 document.querySelector('#open-search').onclick=()=>{dialogState='search';render();};
 document.querySelectorAll('[data-dialog]').forEach(b=>b.onclick=()=>{dialogState=b.dataset.dialog;render();});
 document.querySelectorAll('[data-close-dialog]').forEach(b=>b.onclick=()=>{dialogState=null;render();});
 document.querySelectorAll('[data-open-quote]').forEach(b=>b.onclick=()=>{selectedQuoteId=b.dataset.openQuote;quoteTab='estimate';dialogState=null;location.hash='quotes';render();});
 document.querySelectorAll('[data-approval-tab]').forEach(b=>b.onclick=()=>{approvalTab=b.dataset.approvalTab;render();});
 document.querySelectorAll('[data-task-filter]').forEach(b=>b.onclick=()=>{taskFilter=b.dataset.taskFilter;render();});
 document.querySelectorAll('[data-open-plan]').forEach(b=>b.onclick=()=>{selectedPlanId=b.dataset.openPlan;location.hash='plans';render();});
 document.querySelector('[data-clear-plan]')?.addEventListener('click',()=>{selectedPlanId=null;render();});
 document.querySelector('[data-export-review]')?.addEventListener('click',exportReviewPack);
 document.querySelectorAll('[data-quote-tab]').forEach(b=>b.onclick=()=>{quoteTab=b.dataset.quoteTab;render();});
 bindCommandResults();document.querySelector('#command-search')?.addEventListener('input',e=>{document.querySelector('#command-list').innerHTML=commandOptions(e.target.value);bindCommandResults();});
 document.querySelector('#patient-search')?.addEventListener('input',e=>{patientSearch=e.target.value;const input=document.querySelector('#patient-search'),pos=input.selectionStart;render();const next=document.querySelector('#patient-search');next.focus();next.setSelectionRange(pos,pos);});
 document.querySelector('#role-perspective')?.addEventListener('change',e=>run(async()=>{const session=await api('/api/login',{username:e.target.value});user=session.user;csrf=session.csrf;window.auditData=null;selectedPlanId=null;dialogState=null;quoteTab='estimate';taskFilter='all';approvalTab=user.role==='reviewer'?'pricing':'clinical';location.hash='overview';await refresh();toast(`${workspaceFor(user.role).name} workspace ready.`);}));
 document.querySelectorAll('a[href="designer.html"]').forEach(a=>a.onclick=()=>{try{sessionStorage.setItem('clarity-design-seed',JSON.stringify({version:'role-workspaces-v1',html:document.querySelector('.shell').outerHTML,page:location.hash.slice(1)||'overview'}));}catch{}});
}
document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key==='k'){e.preventDefault();dialogState='search';render();}});

function metricCards(items){return `<div class="stats">${items.map(([label,value,detail,i])=>`<div class="stat"><div class="stat-top">${esc(label)}<span class="stat-icon">${icon(i)}</span></div><b>${esc(value)}</b><div class="stat-foot">${esc(detail)}</div></div>`).join('')}</div>`;}
function taskButton(t){return t.kind==='quote'?`<button class="secondary" data-open-quote="${t.id}">${esc(t.action)}</button>`:t.kind==='plan'?`<button class="secondary" data-open-plan="${t.id}">${esc(t.action)}</button>`:t.kind==='patient'?`<button class="secondary" data-patient="${t.id}">${esc(t.action)}</button>`:`<a class="button secondary" href="#${t.page}">${esc(t.action)}</a>`;}
function taskRows(tasks){return tasks.length?tasks.map(t=>`<article class="worklist-row"><span class="task-symbol ${t.priority==='Blocked'?'attention':''}">${icon(t.kind==='plan'?'tooth':t.kind==='quote'?'sparkle':t.kind==='patient'?'users':'wallet')}</span><div class="task-content"><div class="task-kicker">${esc(patient(t.patientId))}${t.family?`<span> · ${esc(family(t.family))}</span>`:''}</div><h3>${esc(t.title)}</h3><p>Next owner: ${esc(t.owner)}</p></div><div class="task-action">${pill(t.priority,['Blocked','Due','Review needed'].includes(t.priority))}${taskButton(t)}</div></article>`).join(''):`<div class="empty compact-empty">${icon('check')}<h3>No outstanding tasks in this view</h3><p>New tasks appear as patients move through their care journey.</p></div>`;}
function overview(){
 const profile=workspaceFor(user.role),s=summarize(workspace),all=worklist(workspace,user.role),tasks=taskFilter==='attention'?all.filter(t=>t.priority!=='Routine'):all;
 const clinicalDue=s.appointments.filter(a=>Date.parse(a.when)<=Date.now()).length;
 const items=can('patient')?[['Your care plans',s.activePlans.length,'Active treatment journeys','tooth'],['Estimates to review',s.consents.length,'Your consent is the next step','check'],['Your balance',money(s.balance),'Remaining on issued estimates','wallet'],['Upcoming visits',s.appointments.length,'Scheduled appointments','calendar']]:can('clinician')?[['Clinical reviews',s.drafts.length,'Treatment plans awaiting you','tooth'],['Due visits',clinicalDue,'Ready for clinical completion','calendar'],['Approved care plans',s.approved.length,'Active clinical pathways','check'],['Pricing exceptions',s.reviews.length,'Owned by the pricing reviewer','shield']]:can('reviewer')?[['Open exceptions',s.reviews.length,'Need a review disposition','shield'],['Reviewed exceptions',workspace.quotes.filter(q=>q.route==='REVIEW'&&q.disposition).length,'Decisions remain traceable','check'],['Issued estimates',workspace.quotes.filter(q=>q.route==='ISSUED').length,'Policy checks completed','sparkle'],['Clinical handoffs',s.drafts.length,'Awaiting clinician review','tooth']]:can('admin')?[['Active care plans',s.activePlans.length,'Current delivery portfolio','tooth'],['Clinical approvals',s.drafts.length,'Awaiting clinical owner','check'],['Pricing exceptions',s.reviews.length,'Unresolved review decisions','shield'],['Patient balance',money(s.balance),'Across issued estimates','wallet']]:[['Patients',workspace.patients.length,'Connected patient records','users'],['Clinical handoffs',s.drafts.length,'Awaiting clinician approval','tooth'],['Patient decisions',s.consents.length+s.offers.length,'Estimate and offer consents','check'],['Scheduled visits',s.appointments.length,'Current appointment list','calendar']];
 const actions=can('coordinator','clinician')?`<button data-dialog="plan">${icon('plus')}New treatment plan</button>`:can('admin')?`<button data-export-review>${icon('download')}Export leadership brief</button>`:can('reviewer')?'<a class="button" href="#approvals">Open approval center</a>':'';
 return title(profile.title,profile.description,actions)+`<section class="role-banner"><div class="role-banner-icon">${icon(profile.icon)}</div><div><span class="role-banner-label">${esc(profile.name)}</span><h2>${can('admin')?'Oversight with clear accountability.':can('clinician')?'Clinical judgment leads the journey.':can('patient')?'Understand first. Choose when you are ready.':can('reviewer')?'Explain the exception. Preserve the controls.':'Prepare. Coordinate. Follow through.'}</h2></div><span class="role-banner-tag">${can('patient')?'Your care, at a glance':'Role-focused workspace'}</span></section>`+metricCards(items)+`<div class="role-columns"><section class="panel flush worklist-panel"><div class="panel-head"><div><div class="eyebrow">${can('admin')?'DECISIONS & HANDOFFS':'PRIORITIZED WORK'}</div><h2>${esc(profile.focus)}</h2><p class="small">${all.length} ${all.length===1?'task':'tasks'} · each item names the next owner</p></div></div><div class="worklist-filters" aria-label="Worklist filters"><button class="segment ${taskFilter==='all'?'active':''}" data-task-filter="all">All tasks <span>${all.length}</span></button><button class="segment ${taskFilter==='attention'?'active':''}" data-task-filter="attention">Needs attention <span>${all.filter(t=>t.priority!=='Routine').length}</span></button></div>${taskRows(tasks)}</section><aside class="role-side"><section class="panel"><div class="panel-head"><h2>${can('admin')?'Decision ownership':'Care journey'}</h2>${icon('layers')}</div>${careJourney(s)}<a class="text-button" href="#${can('patient')?'plans':'approvals'}">${can('patient')?'See my treatment':'View approval responsibilities'}</a></section><section class="panel"><div class="panel-head"><h2>${can('admin')?'Delivery pulse':'Appointments'}</h2>${icon('calendar')}</div>${can('admin')?`<div class="row"><span>Patient acceptances</span><strong>${s.accepted.length}</strong></div><div class="row"><span>Offers with the patient</span><strong>${s.offers.length}</strong></div><div class="row"><span>Awaiting provider funding</span><strong>${s.readyFunding.length}</strong></div><p class="section-note">Counts come from the current workspace. Financial results appear only after recorded events.</p>`:s.appointments.length?s.appointments.slice(0,3).map(a=>`<div class="appointment-item"><span class="appointment-calendar">${new Date(a.when).toLocaleDateString('en-US',{month:'short'})}<b>${new Date(a.when).getDate()}</b></span><span><strong>${esc(can('patient')?family(a.family):patient(a.patientId))}</strong><small>${esc(new Date(a.when).toLocaleString('en-US',{weekday:'short',hour:'numeric',minute:'2-digit'}))}</small></span></div>`).join(''):`<div class="appointment-empty">${icon('calendar')}<p>No visits scheduled yet.</p><span>${can('patient')?'Your care team will coordinate your next appointment.':'Open a treatment plan to coordinate the next visit.'}</span></div>`}</section></aside></div>`;
}
function careJourney(s){return `<ol class="care-journey"><li><span>${icon('tooth')}</span><div><strong>Clinical review</strong><small>Dentist / clinician</small><em>${s.drafts.length} awaiting review</em></div></li><li><span>${icon('sparkle')}</span><div><strong>Pricing verification</strong><small>Pricing policy & review team</small><em>${s.reviews.length} open exceptions</em></div></li><li><span>${icon('check')}</span><div><strong>Patient choice</strong><small>Patient consent</small><em>${s.consents.length} estimates to review</em></div></li><li><span>${icon('wallet')}</span><div><strong>Financing & care</strong><small>Patient, provider & care team</small><em>${s.readyFunding.length} awaiting funding</em></div></li></ol>`;}
function approvals(){
 const s=summarize(workspace),tabs=[['clinical','Clinical review',s.drafts.length],['pricing','Pricing exceptions',s.reviews.length],['consent','Patient decisions',s.consents.length+s.offers.length],['ownership','Roles & authority',null]],active=tabs.some(t=>t[0]===approvalTab)?approvalTab:'clinical';
 let content='';
 if(active==='clinical')content=`<div class="approval-intro"><div><h2>Clinical treatment review</h2><p>A clinician reviews the treatment details before pricing. Coordination and executive roles can track the handoff.</p></div>${pill('Clinical authority')}</div>${s.drafts.length?s.drafts.map(p=>`<article class="approval-card"><div class="approval-card-head"><div class="person"><span class="avatar lilac">${icon('tooth')}</span><span><strong>${esc(patient(p.patientId))}</strong><small>${esc(family(p.family))}</small></span></div>${pill('Awaiting clinical review',true)}</div><div class="approval-facts"><span>Chair time<strong>${p.minutes} minutes</strong></span><span>Laboratory cost<strong>${money(Math.round(p.lab*100))}</strong></span><span>Plan version<strong>v${p.version}</strong></span></div><div class="approval-owner"><span>${icon('shield')}Decision owner: dentist / clinician</span>${can('clinician')?`<button class="secondary" data-open-plan="${p.id}">Review clinical details</button>`:`<button class="secondary" data-open-plan="${p.id}">View treatment plan</button>`}</div><p class="section-note">Approval is recorded from the treatment plan after the clinician has reviewed the full details.</p></article>`).join(''):emptyApproval('No clinical reviews outstanding','Treatment drafts will appear here when they are ready for review.')}`;
 if(active==='pricing')content=`<div class="approval-intro"><div><h2>Pricing exceptions</h2><p>Review the reason and supporting model evidence. A disposition routes follow-up; it does not override pricing constraints.</p></div>${pill('Reviewer-owned')}</div>${s.reviews.length?s.reviews.map(q=>`<article class="approval-card"><div class="approval-card-head"><div class="person"><span class="avatar lilac">${icon('shield')}</span><span><strong>${esc(patient(q.patientId))}</strong><small>${esc(family(q.input.family))}</small></span></div>${pill('Issue blocked',true)}</div><div class="exception-reason"><strong>${esc(q.code)}</strong><p>${esc(q.reason)}</p></div><div class="approval-owner"><span>Decision owner: pricing & risk reviewer</span><button class="secondary" data-open-quote="${q.id}">Inspect decision evidence</button></div></article>`).join(''):emptyApproval('No open pricing exceptions','Issued estimates have passed the configured pricing checks.')}`;
 if(active==='consent')content=`<div class="approval-intro"><div><h2>Patient decisions</h2><p>Clinical approval, estimate acceptance and financing consent are separate decisions. The care team coordinates the conversation.</p></div>${pill('Patient-owned')}</div>${taskRows(worklist(workspace,'patient').filter(t=>t.kind==='quote'||t.kind==='finance'))}`;
 if(active==='ownership')content=`<div class="approval-intro"><div><h2>Clear authority at every handoff</h2><p>Leadership oversight supports clinical and patient decisions. The responsible role records each decision in its own workflow.</p></div></div><div class="table-wrap"><table class="authority-table"><thead><tr><th>Decision</th><th>Accountable owner</th><th>What the workspace enables</th></tr></thead><tbody>${[['Patient preparation','Nursing & coordination','Create records, coordinate visits and track consent.'],['Treatment approval','Dentist / clinician','Review and approve clinical plans; complete due visits.'],['Pricing verification','Pricing policy / risk reviewer','Inspect evidence; route exceptions for source or policy rework.'],['Treatment acceptance','Patient','Review itemized amounts and record acceptance.'],['Financing offer acceptance','Patient','Give separate consent to the provider offer.'],['Funding outcome','Financing provider','Provider events update the financing ledger through the configured adapter.'],['Delivery oversight','Executive / director','Review readiness, unresolved handoffs, model evidence and audit history.']].map(([a,b,c])=>`<tr><td><strong>${a}</strong></td><td>${b}</td><td>${c}</td></tr>`).join('')}</tbody></table></div><div class="insight-callout">${icon('shield')}<div><strong>Authority follows the decision.</strong><p>Nursing and coordination share the coordinator permissions. Clinical approval remains clinician-only. The current financing workspace uses the local sandbox adapter.</p></div></div>`;
 return title('Every decision has an owner.','A shared approval center for clinical handoffs, pricing exceptions and patient choices.',can('admin')?`<button data-export-review>${icon('download')}Export leadership brief</button>`:'')+`<section class="approval-summary-strip"><div><span>Clinical reviews</span><strong>${s.drafts.length}</strong></div><div><span>Pricing exceptions</span><strong>${s.reviews.length}</strong></div><div><span>Patient decisions</span><strong>${s.consents.length+s.offers.length}</strong></div><div><span>Awaiting funding</span><strong>${s.readyFunding.length}</strong></div></section><section class="panel approval-panel"><div class="approval-tabs" role="group" aria-label="Approval categories">${tabs.map(([id,label,count])=>`<button class="segment ${active===id?'active':''}" data-approval-tab="${id}" aria-pressed="${active===id}">${label}${count!==null?`<span>${count}</span>`:''}</button>`).join('')}</div>${content}</section>`;
}
function emptyApproval(h,p){return `<div class="empty compact-empty">${icon('check')}<h3>${h}</h3><p>${p}</p></div>`;}
function exportReviewPack(){
 const s=summarize(workspace),brief={title:'Clarity Dental leadership review',productOwner:'Andrews Mensah',generatedAt:new Date().toISOString(),runtime:STUDIO?'Browser workspace':'Node / SQLite',counts:{activeCarePlans:s.activePlans.length,clinicalReviews:s.drafts.length,pricingExceptions:s.reviews.length,patientEstimateDecisions:s.consents.length,patientOfferDecisions:s.offers.length,awaitingFunding:s.readyFunding.length,remainingBalanceCents:s.balance},clinicalHandoffs:s.drafts.map(p=>({planId:p.id,patientReference:patient(p.patientId),treatment:family(p.family),version:p.version,owner:'Dentist / clinician'})),pricingExceptions:s.reviews.map(q=>({decisionId:q.id,reason:q.reason,code:q.code,version:q.version,owner:'Pricing & risk reviewer'})),ownership:{clinical:'Dentist / clinician',pricingException:'Pricing & risk reviewer',estimateConsent:'Patient',offerConsent:'Patient',funding:'Financing provider',oversight:'Executive / director'},scope:'Review summary of current workspace records; approval decisions are recorded in their corresponding workflows.'};
 const url=URL.createObjectURL(new Blob([JSON.stringify(brief,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='clarity-leadership-review.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Leadership brief exported.');
}

start();
